def compute_a(N):
    a = {}
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # We need a_{n-1}. Since we are iterating, this is available.
        a_n_minus_1 = a[n-1]

        # First term: a_{a_{n-1}}
        idx1 = a_n_minus_1
        if idx1 not in a:
            # This should theoretically not happen if we calculate sequentially
            raise IndexError(f"Index {idx1} required for a_{n} is out of bounds for calculated sequence.")
        term1 = a[idx1]

        # Second term: a_{n - a_{n-1}}
        idx2 = n - a_n_minus_1
        if idx2 <= 0 or idx2 not in a:
            raise IndexError(f"Index {idx2} required for a_{n} is out of bounds or non-positive.")
        term2 = a[idx2]

        a[n] = term1 + term2

    return a

