def calculate_a_n(N):
    # Array to store a_n. We use 1-based indexing, so size is N+1.
    a = [0] * (N + 1)

    # Base cases
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    # Compute for n = 3 up to N
    for n in range(3, N + 1):
        # Recurrence: a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # Index 1: a_{n-1}
        idx1 = a[n-1]

        # Index 2: n - a_{n-1}
        idx2 = n - a[n-1]

        # Since a_k <= k, both idx1 and idx2 are guaranteed to be <= n-1 
        # (and thus already computed), provided the sequence growth rate holds.
        # We must ensure they are positive, which was proven earlier.
        if idx1 > 0 and idx2 > 0:
            a[n] = a[idx1] + a[idx2]
        else:
            # This should not happen based on previous analysis
            raise ValueError(f"Invalid index encountered at n={n}")

    return a[N]

